{
  "investigate": [],
  "hypotheses": [
    {
      "service": "workflow",
      "kind": "resource_exhaustion",
      "mechanism": "Workflow service exceeded its disk quota (1210.2 MB used vs 1000 MB quota), causing it to fail and disrupt order fulfillment.",
      "supporting": ["E10", "E34"],
      "refuting": [],
      "explains": ["M1_throughput_drop"],
      "repair_plan": [
        {
          "action": "restart_service",
          "params": {
            "service": "workflow"
          }
        }
      ]
    },
    {
      "service": "worker",
      "kind": "bad_deploy",
      "mechanism": "Worker v2.0 deploy introduced a bug causing false disk quota errors despite sufficient disk space, leading to message retries and dead letters.",
      "supporting": ["E14", "E15", "E18", "E33"],
      "refuting": ["E32"],
      "explains": ["M2_error_burst", "M3_dead_letters"],
      "repair_plan": [
        {
          "action": "rollback_service",
          "params": {
            "service": "worker"
          }
        }
      ]
    },
    {
      "service": "sync-job",
      "kind": "runtime_fault",
      "mechanism": "Sync-job process is stuck in a bad state, causing sync failures despite sufficient disk quota.",
      "supporting": ["E3", "E6", "E16"],
      "refuting": ["E32"],
      "explains": [],
      "repair_plan": [
        {
          "action": "restart_service",
          "params": {
            "service": "sync-job"
          }
        }
      ]
    }
  ],
  "summary": "Workflow disk exhaustion and worker bad deploy are causing throughput drop and errors; sync-job has a separate runtime fault."
}
